const net = require("net");
const path = require("path");
const os = require("os");
const fs = require("fs");
// Node.js's net from an npm package: a TCP echo server and clients, IPv6, unix sockets, errors.
// Prints what it found; the same package under Node.js prints the same.
function echoServer(server) {
  server.on("connection", (sock) => {
    sock.on("data", (d) => sock.write(d.toString().toUpperCase()));
    sock.on("end", () => sock.end());
  });
}
function roundTrip(connectArgs, message) {
  return new Promise((resolve, reject) => {
    const c = net.connect(...connectArgs);
    let got = "";
    c.on("connect", () => c.end(message));
    c.on("data", (d) => { got += d; });
    c.on("close", () => resolve(got));
    c.on("error", reject);
  });
}
module.exports = async function run() {
  const server = net.createServer();
  echoServer(server);
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  const { address, family, port } = server.address();
  console.log("listening", address, family, port > 0);
  console.log("echo", await roundTrip([port, "127.0.0.1"], "hello"));
  const big = "x".repeat(1 << 20);
  console.log("big", (await roundTrip([port, "127.0.0.1"], big)).length);
  const many = await Promise.all([1, 2, 3, 4, 5].map((i) => roundTrip([{ port, host: "127.0.0.1" }], `c${i}`)));
  console.log("concurrent", many.join(","));
  const sock = net.connect(port, "127.0.0.1");
  await new Promise((r) => sock.on("connect", r));
  console.log("socket", sock.remoteAddress, sock.remotePort === port, sock.localAddress, typeof sock.localPort, sock.remoteFamily);
  sock.setNoDelay(true);
  sock.setKeepAlive(true, 1000);
  sock.destroy();
  await new Promise((r) => server.close(r));
  console.log("closed", server.listening);
  const v6 = net.createServer();
  echoServer(v6);
  await new Promise((r) => v6.listen(0, "::1", r));
  console.log("ipv6", v6.address().family, await roundTrip([v6.address().port, "::1"], "six"));
  v6.close();
  const sockPath = path.join(os.tmpdir(), `barm-net-${process.pid}.sock`);
  try { fs.unlinkSync(sockPath); } catch {}
  const unix = net.createServer();
  echoServer(unix);
  await new Promise((r) => unix.listen(sockPath, r));
  console.log("unix", await roundTrip([sockPath], "pipe"));
  unix.close();
  const refused = await new Promise((resolve) => {
    const c = net.connect(1, "127.0.0.1");
    c.on("error", (e) => resolve(`${e.code} ${e.syscall} ${e.address} ${e.port}`));
  });
  console.log("refused", refused);
  const inUse = net.createServer();
  await new Promise((r) => inUse.listen(0, "127.0.0.1", r));
  const clash = net.createServer();
  const clashErr = await new Promise((resolve) => {
    clash.on("error", (e) => resolve(`${e.code} ${e.syscall}`));
    clash.listen(inUse.address().port, "127.0.0.1");
  });
  console.log("in use", clashErr);
  inUse.close();
  const dns = await new Promise((resolve) => {
    const s = net.createServer((c) => c.end("by name"));
    s.listen(0, "localhost", () => {
      const c = net.connect(s.address().port, "localhost");
      let got = "";
      c.on("data", (d) => { got += d; });
      c.on("close", () => { s.close(); resolve(got); });
    });
  });
  console.log("localhost", dns);
  // net.BlockList and net.SocketAddress
  const b = new net.BlockList();
  b.addAddress('1.2.3.4');
  b.addRange('10.0.0.1', '10.0.0.9');
  b.addSubnet('8592:757c:efae:4e45::', 64, 'ipv6');
  b.addSubnet('192.168.0.0', 16);
  console.log(b.rules.join(' | '));
  console.log(b.check('10.0.0.5'), b.check('::ffff:1.2.3.4', 'ipv6'), b.check('8592:757c:efae:4e45::f', 'ipv6'), b.check('1.2.3.5'), b.check('192.168.44.1'), b.check('192.169.0.1'));
  try {
    b.addRange('10.0.0.9', '10.0.0.1');
  } catch (e) {
    console.log('range', e.code);
  }
  const s = new net.SocketAddress({ address: '::1', port: 80, family: 'ipv6' });
  console.log(s.address, s.port, s.family, s.flowlabel, JSON.stringify(s.toJSON()));
  try {
    new net.SocketAddress({ address: 'nope' });
  } catch (e) {
    console.log('invalid', e.code, e.message);
  }
  console.log('parse', JSON.stringify(net.SocketAddress.parse('1.2.3.4:8080')), net.SocketAddress.parse('nope'));
};
